package com.syntona.util

import kotlin.jvm.JvmOverloads
import kotlin.random.Random

/**
 * Generate a sequence of integers based on a recursive mining of
 * previous material.
 * Notes are generated by one of the following formula:
 *
 *   value[n] = value[n-delay] + offset
 *
 * The parameters length and transpose are randomly generated.
 */
class RecursiveSequence @JvmOverloads constructor(
    var maxValue: Int = 25,
    var maxInterval: Int = 7,
    arraySize: Int = 64
) {
    val maxDelay: Int = arraySize / 2
    var delay: Int = 1
    var offset: Int = 0
    val values: IntArray = IntArray(arraySize) { maxValue / 2 }
    val enables: BooleanArray = BooleanArray(arraySize)
    var cursor: Int = 0
    var countdown: Int = -1
    var actualDensity: Double = 0.0

    /** Note density, from 0.0 to 1.0. */
    var density: Double = 0.5

    var beatsPerMeasure: Int = 8

    init {
        for (i in enables.indices) {
            enables[i] = isNextEnabled(false)
        }
    }

    /** Determine whether next in sequence should occur. */
    fun isNextEnabled(preference: Boolean): Boolean {
        var pref = preference
        // Calculate note density using low pass IIR filter.
        val newDensity = (actualDensity * 0.9) + (if (pref) 0.1 else 0.0)
        // Invert enable to push density towards desired level, with hysteresis.
        if (pref && (newDensity > ((density * 0.7) + 0.3))) {
            pref = false
        } else if (!pref && (newDensity < (density * 0.7))) {
            pref = true
        }
        actualDensity = (actualDensity * 0.9) + (if (pref) 0.1 else 0.0)
        return pref
    }

    /** Generate values that are powers of 2. */
    fun randomPowerOf2(maxExp: Int): Int {
        return 1 shl Random.nextInt(maxExp + 1)
    }

    /** Random number evenly distributed from -maxInterval to +maxInterval */
    fun randomEvenInterval(): Int {
        return Random.nextInt(-maxInterval, maxInterval + 1)
    }

    fun calcNewOffset() {
        offset = randomEvenInterval()
    }

    fun randomize() {
        delay = randomPowerOf2(4)
        calcNewOffset()
    }

    /** Change parameters based on random countdown. */
    fun next(): Int {
        // If this sequence is finished, start a new one.
        if (countdown-- < 0) {
            randomize()
            countdown = randomPowerOf2(3)
        }
        return nextValue()
    }

    /** Change parameters using a probability based on beatIndex. */
    fun next(beatIndex: Int): Int {
        val beatMod = beatIndex % beatsPerMeasure
        when (beatMod) {
            0 -> if (Random.nextDouble() < 0.90) randomize()
            2, 6 -> if (Random.nextDouble() < 0.15) randomize()
            4 -> if (Random.nextDouble() < 0.30) randomize()
            else -> if (Random.nextDouble() < 0.07) randomize()
        }
        return nextValue()
    }

    /** Generate nextValue based on current delay and offset */
    fun nextValue(): Int {
        // Generate index into circular value buffer.
        var idx = cursor - delay
        if (idx < 0) idx += values.size

        // Generate new value. Calc new offset if too high or low.
        var nextVal = 0
        var timeout = 100
        while (timeout > 0) {
            nextVal = values[idx] + offset
            if (nextVal >= 0 && nextVal < maxValue) break
            // Prevent endless loops when maxValue changes.
            if (nextVal > maxValue + maxInterval - 1) {
                nextVal = maxValue
                break
            }
            calcNewOffset()
            timeout--
        }
        if (timeout <= 0) {
            println("RecursiveSequence: nextValue timed out. offset = $offset")
            nextVal = maxValue / 2
            offset = 0
        }

        // Save new value in circular buffer.
        values[cursor] = nextVal

        val playIt = isNextEnabled(enables[idx])
        enables[cursor] = playIt
        cursor++
        if (cursor >= values.size) cursor = 0

        return if (playIt) nextVal else -1
    }
}
